SELECT LAG(SUM(x4.v160206 / x4.v160207), 1, SUM(x4.v160206 / x4.v160206)) OVER (ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), FIRST_VALUE(x4.v160206) OVER (ORDER BY x4.v160207 RANGE BETWEEN INTERVAL (ROW_NUMBER() OVER ()) HOUR PRECEDING AND CURRENT ROW) FROM v160205 AS x4 WINDOW x1 AS (PARTITION BY x4.v160207 ORDER BY x4.v160206 ROWS BETWEEN 1 FOLLOWING AND 2 FOLLOWING)